import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CQdiwDJy.js";const p=JSON.parse('{"title":"Safety model","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/safety.md","filePath":"en/reference/safety.md","lastUpdated":1788601681000}'),r={name:"en/reference/safety.md"};function n(d,e,s,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="safety-model" tabindex="-1">Safety model <a class="header-anchor" href="#safety-model" aria-label="Permalink to &quot;Safety model&quot;">​</a></h1><p>Tau&#39;s core promise: <strong>no AI-generated action reaches your machine without passing a deterministic, tested gate that the AI does not control.</strong> The design compresses to one sentence: <strong>the AI proposes, rules review, the human decides.</strong> Every mechanism is deterministic code — there is no &quot;the AI thinks it&#39;s fine&quot; anywhere.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ol><li><strong>AI proposes, code disposes.</strong> The model&#39;s output is untrusted data until <code>validatePlanResponse()</code> (strict zod) and <code>reviewPlan()</code> (pure functions) have accepted it.</li><li><strong>The reviewer is deterministic.</strong> No network, no randomness, no clock. Same plan → same verdict. Fully unit-tested, including benign near-misses.</li><li><strong>Dry-run by default.</strong> <code>file.rename</code>, <code>text.replace</code> and (since 0.4.0) <code>file.write</code> — the first-party mutating tools — preview unless <code>execute:true</code> is explicit. <code>file.write</code> additionally refuses paths outside the workspace and OS-managed locations; the safety reviewer re-checks every planned write path independently (system location → blocked, workspace escape → high).</li><li><strong>No delete primitive.</strong> There is deliberately no <code>file.delete</code> tool. The AI planner must never have a first-party deletion primitive. Deletion goes through shell steps — which are scanned, and which require confirmation.</li><li><strong><code>--yes</code> is honest.</strong> It auto-approves low risk (and medium only with <code>tau config set allowMediumAutoApprove true</code>). High risk always needs a human keystroke. Blocked is unreachable by anyone.</li><li><strong>Everything is recorded.</strong> Every run — direct, planned, denied, cancelled — lands in <code>$TAU_HOME/history.jsonl</code>.</li></ol><h2 id="three-gates" tabindex="-1">Three gates <a class="header-anchor" href="#three-gates" aria-label="Permalink to &quot;Three gates&quot;">​</a></h2><ol><li><strong>Plan validation</strong> — provider output must be strict JSON (zod schema, <code>additionalProperties: false</code>); loose output (code fences, extra fields) is rejected outright.</li><li><strong>Deterministic review</strong> — <code>reviewPlan()</code> grades the plan by rules: allow / review / deny, with itemized issues. The reviewer independently re-checks every write path, forming defense in depth with the tool&#39;s own checks.</li><li><strong>Execution confirmation</strong> — deny never runs; high-risk demands explicit confirmation (CLI interactive, WebUI card-local checkbox); medium writes default to dry-run and need <code>execute: true</code>; in agent mode medium+ rounds pause inline for approval — <strong>there is never a blanket pre-approval</strong>.</li></ol><h2 id="one-execution-channel" tabindex="-1">One execution channel <a class="header-anchor" href="#one-execution-channel" aria-label="Permalink to &quot;One execution channel&quot;">​</a></h2><p><code>runPlan()</code> is the only execution channel, and it reviews <strong>again</strong> inside. Every front door (CLI/TUI/WebUI), every mode (ask/goal), every provider converges here. There is no &quot;provider runs a command directly&quot; path.</p><h2 id="risk-levels" tabindex="-1">Risk levels <a class="header-anchor" href="#risk-levels" aria-label="Permalink to &quot;Risk levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Meaning</th><th>What can run it</th></tr></thead><tbody><tr><td><code>low</code></td><td>read-only / harmless output</td><td>everyone, <code>--yes</code> included</td></tr><tr><td><code>medium</code></td><td>mutating first-party tool, dry-run available</td><td>interactive confirm, or <code>--yes</code> + opt-in config</td></tr><tr><td><code>high</code></td><td>caution-list shell ops (<code>rm</code>, <code>chmod</code>, <code>kill</code>, force git ops, PowerShell destructives like <code>Remove-Item -Recurse</code> / <code>Format-Volume</code> / <code>Set-ExecutionPolicy</code> / <code>Invoke-Expression</code>)</td><td>interactive confirm ONLY</td></tr><tr><td><code>blocked</code></td><td>deny-list match or structural violation</td><td>NOBODY. Plan refused, exit 2</td></tr></tbody></table><h2 id="deny-list-verdict-deny-before-any-confirmation" tabindex="-1">Deny list (verdict: deny, before any confirmation) <a class="header-anchor" href="#deny-list-verdict-deny-before-any-confirmation" aria-label="Permalink to &quot;Deny list (verdict: deny, before any confirmation)&quot;">​</a></h2><p>Highlights — see <code>packages/engine/src/safety.ts DENY_PATTERNS</code> for the full list:</p><ul><li><code>rm -rf /</code> and home-directory recursive deletes</li><li><code>sudo</code>, <code>su</code> in any position</li><li><code>mkfs</code>, <code>dd ... of=/dev/*</code>, <code>&gt; /dev/sd*</code></li><li><code>curl … | sh</code> / <code>wget … | bash</code> (installer pipes)</li><li><code>chmod -R 777 /</code>, fork bombs <code>:(){ :|:&amp; };:</code></li><li><code>shutdown</code> / <code>reboot</code> / <code>halt</code> / <code>poweroff</code></li><li><code>git push --force</code>, <code>DROP TABLE</code> / <code>DROP DATABASE</code></li><li>history erasure (<code>history -c</code>), known_hosts tampering</li></ul><p>Each pattern ships with a paired test: the positive match AND a benign look-alike that must NOT match (over-blocking is treated as a bug too).</p><h2 id="caution-list-escalate-to-high-risk" tabindex="-1">Caution list (escalate to high risk) <a class="header-anchor" href="#caution-list-escalate-to-high-risk" aria-label="Permalink to &quot;Caution list (escalate to high risk)&quot;">​</a></h2><p><code>rm</code>, <code>chown</code>, <code>chmod</code>, <code>kill/pkill/killall</code>, <code>git reset --hard</code> / <code>git clean -f</code> / <code>git checkout --</code>, <code>npm publish/uninstall</code>, <code>pip uninstall</code>, <code>curl</code>/<code>wget</code> (bare), writes into <code>/etc|/usr|/bin</code>, docker destructive ops, <code>truncate</code>, <code>tee /etc/...</code></p><h2 id="structural-limits" tabindex="-1">Structural limits <a class="header-anchor" href="#structural-limits" aria-label="Permalink to &quot;Structural limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>steps per plan</td><td>≤ 10</td></tr><tr><td>shell command length</td><td>≤ 2000 chars</td></tr><tr><td>output captured</td><td>≤ 200 KB (hard kill beyond)</td></tr><tr><td>command timeout</td><td>config <code>timeout</code> (default 30 s)</td></tr><tr><td>tool args</td><td>validated per-tool; unknown tool names → deny</td></tr><tr><td>plan JSON</td><td>zod <code>.strict()</code> — no extra keys, no invented enums</td></tr></tbody></table><h2 id="network-guards" tabindex="-1">Network guards <a class="header-anchor" href="#network-guards" aria-label="Permalink to &quot;Network guards&quot;">​</a></h2><ul><li><code>net.fetch</code> refuses private/loopback/link-local targets unless <code>allowPrivate:true</code> (SSRF guard). Absolute http(s) URLs only.</li><li><code>net.ping</code> rejects shell metacharacters in the host (the tool spawns the system <code>ping</code>, so the host argument must be plain).</li><li><code>net.port</code> is single-host single-port by design; no port-range scanning.</li></ul><h2 id="skill-safety" tabindex="-1">Skill safety <a class="header-anchor" href="#skill-safety" aria-label="Permalink to &quot;Skill safety&quot;">​</a></h2><ul><li>Every skill command is scanned against the deny list at load time; matches become visible validation issues (never silent).</li><li>Declarative commands declare their <code>risk</code>; the reviewer trusts exactly that declaration — nothing more.</li><li>Skills are data: no code from a skill directory is ever executed implicitly.</li></ul><h2 id="plugin-tools" tabindex="-1">Plugin tools <a class="header-anchor" href="#plugin-tools" aria-label="Permalink to &quot;Plugin tools&quot;">​</a></h2><p>External MCP tools are graded <strong>medium unconditionally</strong> — third-party code with first-party reach can never silently auto-execute, whatever it declares. See <a href="/Tau/en/guide/plugins.html">plugins</a> for the full security model.</p><h2 id="streaming-never-weakens-safety-v0-5-0" tabindex="-1">Streaming never weakens safety (v0.5.0) <a class="header-anchor" href="#streaming-never-weakens-safety-v0-5-0" aria-label="Permalink to &quot;Streaming never weakens safety (v0.5.0)&quot;">​</a></h2><p>Streaming changes when text arrives, not how it is handled: a streamed plan still passes the same <code>validatePlanResponse()</code> and <code>reviewPlan()</code>; refusals happen before the stream starts (plain JSON errors). There is no &quot;streaming bypasses the review&quot; shape.</p><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><p>One structured log line per request (including AI token cost); the WebUI settings panel shows only redacted config — API keys never appear in plaintext in logs or the browser.</p><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><p>Tau is not a sandbox. It gates <em>what gets proposed and approved</em>; once you confirm a high-risk step, the OS runs it with your permissions. For true sandboxing, run Tau inside a container (see <code>.devcontainer/</code>).</p>',30)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
